111: // ConvertChannelInternal - convert CLN channel to internal format
112: func ConvertChannelInternal(chans []ClnListChan, id uint64) (*NodeChannelAPIExtended, error) {
113: 	ret := &NodeChannelAPIExtended{
114: 		NodeChannelAPI: NodeChannelAPI{
115: 			ChannelID: id,
116: 			Capacity:  chans[0].Capacity,
117: 			// TODO: we don't have that
118: 			ChanPoint: "none",
119: 		},
120: 		Private: !chans[0].Public,
121: 	}
122: 
123: 	if chans[0].Source < chans[0].Destination {
124: 		ret.Node1Pub = chans[0].Source
125: 		ret.Node2Pub = chans[0].Destination
126: 	} else {
127: 		ret.Node1Pub = chans[0].Destination
128: 		ret.Node2Pub = chans[0].Source
129: 	}
130: 
131: 	maxUpdate := time.Time{}
132: 	for _, one := range chans {
133: 		if time.Time(one.LastUpdate).After(maxUpdate) {
134: 			maxUpdate = time.Time(one.LastUpdate)
135: 		}
136: 
137: 		if one.Source == ret.Node1Pub {
138: 			ret.Node1Policy = &RoutingPolicyAPI{
139: 				TimeLockDelta: uint32(one.Delay),
140: 				Disabled:      !one.Active,
141: 				LastUpdate:    one.LastUpdate,
142: 				BaseFee:       one.FeeBase,
143: 				FeeRate:       one.FeePpm,
144: 				MinHtlc:       ConvertAmount(one.MinHtlc),
145: 				MaxHtlc:       ConvertAmount(one.MaxHtlc),
146: 			}
147: 		} else if one.Source == ret.Node2Pub {
148: 			ret.Node2Policy = &RoutingPolicyAPI{
149: 				TimeLockDelta: uint32(one.Delay),
150: 				Disabled:      !one.Active,
151: 				LastUpdate:    one.LastUpdate,
152: 				BaseFee:       one.FeeBase,
153: 				FeeRate:       one.FeePpm,
154: 				MinHtlc:       ConvertAmount(one.MinHtlc),
155: 				MaxHtlc:       ConvertAmount(one.MaxHtlc),
156: 			}
157: 		} else {
158: 			return nil, ErrInvalidResponse
159: 		}
160: 	}
161: 
162: 	ret.LastUpdate = entities.JsonTime(maxUpdate)
163: 
164: 	return ret, nil
165: }
