func processRawEntries[T any](entries [][]byte, implName string, extractTime func(T) int64) ([]RawMessage, *ResponseRawPagination, error) {
	respPagination := &ResponseRawPagination{UseTimestamp: true}
	ret := make([]RawMessage, 0, len(entries))

	minTime := time.Unix(1<<63-1, 0)
	maxTime := time.Unix(0, 0)

	for _, one := range entries {
		var gettime T
		err := json.Unmarshal(one, &gettime)
		if err != nil {
			return nil, respPagination, err
		}

		t := time.Unix(extractTime(gettime), 0)

		if t.Before(minTime) {
			minTime = t
		}
		if t.After(maxTime) {
			maxTime = t
		}

		m := RawMessage{
			Implementation: implName,
			Timestamp:      t,
			Message:        one,
		}

