579: func (l *ClnSocketLightningAPI) processRawEntries(entries [][]byte, unmarshalFunc func([]byte) (time.Time, error)) ([]RawMessage, *ResponseRawPagination, error) {
580: 	respPagination := &ResponseRawPagination{UseTimestamp: true}
581: 	ret := make([]RawMessage, 0, len(entries))
582: 
583: 	minTime := time.Unix(1<<63-1, 0)
584: 	maxTime := time.Unix(0, 0)
585: 
586: 	for _, one := range entries {
587: 		t, err := unmarshalFunc(one)
588: 		if err != nil {
589: 			return nil, respPagination, err
590: 		}
591: 
592: 		if t.Before(minTime) {
593: 			minTime = t
594: 		}
595: 		if t.After(maxTime) {
596: 			maxTime = t
597: 		}
598: 
599: 		m := RawMessage{
600: 			Implementation: l.Name,
601: 			Timestamp:      t,
602: 			Message:        one,
603: 		}
604: 
605: 		ret = append(ret, m)
606: 	}
607: 
608: 	respPagination.FirstTime = minTime
609: 	respPagination.LastTime = maxTime
610: 
611: 	return ret, respPagination, nil
612: }
